create function public.canvas_file_version(p jsonb)returns text language sql immutable set search_path=''as $$select md5(jsonb_build_array(p->'id',p->'updated_at',p->'modified_at',p->'size',p->'content-type',p->'display_name')::text)$$;
create table public.canvas_documents(user_id uuid not null references auth.users(id)on delete cascade,course_canvas_id text not null,canvas_file_id text not null,title text not null,content_type text not null,source_version text not null,connection_generation uuid not null,state text not null default 'pending'check(state in('pending','ready','unavailable','no_text','too_large','unsupported','failed')),source_hash text,pages integer,truncated boolean not null default false,extracted_at timestamptz,last_checked_at timestamptz,last_error text,next_attempt_at timestamptz not null default now(),attempts integer not null default 0,lease_token uuid,lease_until timestamptz,primary key(user_id,course_canvas_id,canvas_file_id));
create table public.canvas_document_chunks(user_id uuid not null,course_canvas_id text not null,canvas_file_id text not null,chunk_index integer not null,page integer not null check(page>0),text text not null check(length(text)<=1400),search tsvector generated always as(to_tsvector('english',text))stored,primary key(user_id,course_canvas_id,canvas_file_id,chunk_index),foreign key(user_id,course_canvas_id,canvas_file_id)references public.canvas_documents(user_id,course_canvas_id,canvas_file_id)on delete cascade);
create index canvas_chunk_search on public.canvas_document_chunks using gin(search);
create index canvas_document_queue on public.canvas_documents(user_id,state,next_attempt_at);
do $$declare t text;begin foreach t in array array['canvas_documents','canvas_document_chunks']loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant select on public.%I to authenticated',t);execute format('grant all on public.%I to service_role',t);execute format('create policy owner_read on public.%I for select to authenticated using(user_id=auth.uid()and public.is_approved_user())',t);end loop;end$$;
create function public.canvas_seed_documents(p_user uuid)returns integer language plpgsql security invoker set search_path=''as $$declare n integer;begin
 if not public.canvas_worker_owner(p_user)then raise exception 'Unauthorized'using errcode='42501';end if;
 insert into public.canvas_documents(user_id,course_canvas_id,canvas_file_id,title,content_type,source_version,connection_generation,state)
 select p_user,r.course_canvas_id,r.payload->>'id',left(coalesce(r.payload->>'display_name',r.payload->>'filename','Canvas file'),500),coalesce(r.payload->>'content-type','application/octet-stream'),public.canvas_file_version(r.payload),connection.generation,case when coalesce(r.payload->>'content-type','')in('application/pdf','application/vnd.openxmlformats-officedocument.presentationml.presentation','application/vnd.openxmlformats-officedocument.wordprocessingml.document','text/plain')then 'pending'else 'unsupported'end from public.canvas_records r join public.canvas_connections connection on connection.user_id=r.user_id where r.user_id=p_user and r.resource_type='file'and r.course_canvas_id is not null and r.payload->>'id'~'^\d+$'
 on conflict(user_id,course_canvas_id,canvas_file_id)do update set title=excluded.title,content_type=excluded.content_type,source_version=excluded.source_version,connection_generation=excluded.connection_generation,state=excluded.state,next_attempt_at=now(),last_error=null where canvas_documents.source_version<>excluded.source_version or canvas_documents.connection_generation<>excluded.connection_generation;
 get diagnostics n=row_count;return n;end$$;
create function public.canvas_claim_document(p_user uuid,p_course text,p_file text,p_lease uuid)returns jsonb language plpgsql security invoker set search_path=''as $$declare d public.canvas_documents;g uuid;begin
 if not public.canvas_worker_owner(p_user)then raise exception 'Unauthorized'using errcode='42501';end if;
 select generation into g from public.canvas_connections where user_id=p_user and enabled and expires_at>now();if not found then return null;end if;
 select * into d from public.canvas_documents where user_id=p_user and state in('pending','failed','unavailable')and next_attempt_at<=now()and(lease_until is null or lease_until<now())and(p_course is null or course_canvas_id=p_course)and(p_file is null or canvas_file_id=p_file)order by case when title~*'syllabus|outline'then 0 when title~*'exam|midterm|test'then 1 else 2 end,next_attempt_at,canvas_file_id limit 1 for update skip locked;
 if not found then return null;end if;
 update public.canvas_documents set lease_token=p_lease,lease_until=now()+interval '2 minutes',last_checked_at=now()where user_id=p_user and course_canvas_id=d.course_canvas_id and canvas_file_id=d.canvas_file_id;
 return to_jsonb(d)||jsonb_build_object('generation',g);end$$;
create function public.canvas_finish_document(p_user uuid,p_course text,p_file text,p_lease uuid,p_generation uuid,p_version text,p_metadata jsonb,p_hash text,p_pages integer,p_truncated boolean,p_chunks jsonb)returns void language plpgsql security invoker set search_path=''as $$declare d public.canvas_documents;begin
 if not public.canvas_worker_owner(p_user)or not exists(select 1 from public.canvas_connections where user_id=p_user and generation=p_generation and enabled and expires_at>now())then raise exception 'Connection changed'using errcode='40001';end if;
 select * into d from public.canvas_documents where user_id=p_user and course_canvas_id=p_course and canvas_file_id=p_file for update;
 if not found or d.lease_token is distinct from p_lease or d.lease_until is null or d.lease_until<now()or d.source_version<>p_version or p_metadata->>'id' is distinct from p_file then raise exception 'Document changed'using errcode='40001';end if;
 if not exists(select 1 from public.canvas_records where user_id=p_user and resource_type='file'and canvas_id=p_course||':'||p_file and public.canvas_file_version(payload)=p_version)then raise exception 'Source changed'using errcode='40001';end if;
 if jsonb_array_length(p_chunks)>200 or p_pages not between 0 and 150 then raise exception 'Extraction limit exceeded'using errcode='22023';end if;
 delete from public.canvas_document_chunks where user_id=p_user and course_canvas_id=p_course and canvas_file_id=p_file;
 insert into public.canvas_document_chunks(user_id,course_canvas_id,canvas_file_id,chunk_index,page,text)select p_user,p_course,p_file,x.index,x.page,x.text from jsonb_to_recordset(p_chunks)as x(index integer,page integer,text text);
 update public.canvas_records set payload=p_metadata,synced_at=now()where user_id=p_user and resource_type='file'and canvas_id=p_course||':'||p_file;
 update public.canvas_documents set source_version=public.canvas_file_version(p_metadata),state=case when jsonb_array_length(p_chunks)>0 then 'ready'else 'no_text'end,source_hash=p_hash,pages=p_pages,truncated=p_truncated,extracted_at=now(),last_error=null,lease_token=null,lease_until=null,attempts=0 where user_id=p_user and course_canvas_id=p_course and canvas_file_id=p_file;
end$$;
create function public.canvas_search_materials(p_course text,p_query text)returns table(file_id text,chunk_index integer,title text,page integer,text text,extracted_at timestamptz,truncated boolean)language sql stable security invoker set search_path=''as $$
 select d.canvas_file_id,c.chunk_index,d.title,c.page,c.text,d.extracted_at,d.truncated from public.canvas_document_chunks c join public.canvas_documents d using(user_id,course_canvas_id,canvas_file_id)where d.user_id=auth.uid()and public.is_approved_user()and d.state='ready'and d.course_canvas_id=p_course and(c.search@@websearch_to_tsquery('english',left(p_query,1000))or to_tsvector('english',d.title)@@websearch_to_tsquery('english',left(p_query,1000)))order by ts_rank(setweight(to_tsvector('english',d.title),'A')||c.search,websearch_to_tsquery('english',left(p_query,1000)))desc,d.canvas_file_id,c.chunk_index limit 6
$$;
revoke all on function public.canvas_file_version(jsonb),public.canvas_seed_documents(uuid),public.canvas_claim_document(uuid,text,text,uuid),public.canvas_finish_document(uuid,text,text,uuid,uuid,text,jsonb,text,integer,boolean,jsonb)from public,anon,authenticated;
grant execute on function public.canvas_file_version(jsonb),public.canvas_seed_documents(uuid),public.canvas_claim_document(uuid,text,text,uuid),public.canvas_finish_document(uuid,text,text,uuid,uuid,text,jsonb,text,integer,boolean,jsonb)to service_role;
revoke all on function public.canvas_search_materials(text,text)from public,anon;grant execute on function public.canvas_search_materials(text,text)to authenticated;
